:root {
  --bg: #1a1a2e;
  --card-bg: #16213e;
  --primary: #e94560;
  --text: #f5f5f5;
  --muted: #a0a0b0;
  --focus: #ffcc00;
  --font: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  font-family: var(--font);
  font-size: 16px;
  color: var(--text);
  padding: 1rem;
}

.card {
  background: var(--card-bg);
  border-radius: 1.5rem;
  padding: 2rem 1.5rem;
  width: 100%;
  max-width: 400px;
  text-align: center;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.4);
  border: 2px solid var(--primary);
}

h1 {
  font-size: 1.5rem;
  margin-bottom: 1.5rem;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  color: var(--primary);
}

.mode-switch {
  display: flex;
  gap: 0.5rem;
  justify-content: center;
  margin-bottom: 1.5rem;
}

.mode-btn {
  background: transparent;
  border: 2px solid var(--muted);
  color: var(--muted);
  padding: 0.5rem 1rem;
  border-radius: 0.5rem;
  font-family: var(--font);
  font-size: 1rem;
  cursor: pointer;
  transition: all 0.2s;
  min-height: 44px;
}

.mode-btn:hover {
  border-color: var(--text);
  color: var(--text);
}

.mode-btn:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.mode-btn:active {
  transform: scale(0.97);
}

.mode-btn.active {
  border-color: var(--primary);
  color: var(--primary);
  background: rgba(233, 69, 96, 0.1);
}

.timer {
  font-size: 5rem;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  letter-spacing: 0.05em;
  margin: 1.5rem 0;
  color: var(--text);
  text-shadow: 0 0 20px rgba(233, 69, 96, 0.3);
  line-height: 1.2;
}

.controls {
  display: flex;
  gap: 1rem;
  justify-content: center;
  flex-wrap: wrap;
}

.btn {
  background: transparent;
  border: 2px solid var(--muted);
  color: var(--text);
  padding: 0.75rem 1.5rem;
  border-radius: 0.5rem;
  font-family: var(--font);
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.2s;
  min-width: 100px;
  min-height: 44px;
}

.btn:hover {
  background: rgba(255, 255, 255, 0.1);
  border-color: var(--text);
}

.btn:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.btn:active {
  transform: scale(0.97);
}

.btn.primary {
  background: var(--primary);
  border-color: var(--primary);
  color: #fff;
}

.btn.primary:hover {
  background: #c7354f;
  border-color: #c7354f;
}

@media (max-width: 400px) {
  .timer {
    font-size: 3.5rem;
  }
  .card {
    padding: 1.5rem 1rem;
  }
  .mode-btn {
    font-size: 0.9rem;
    padding: 0.5rem 0.75rem;
  }
  .btn {
    min-width: 80px;
    padding: 0.75rem 1rem;
  }
}

(function() {
  'use strict';

  const WORK_TIME = 25 * 60;
  const BREAK_TIME = 5 * 60;

  let timeLeft = WORK_TIME;
  let timerId = null;
  let isRunning = false;
  let currentMode = 'work';

  const timerDisplay = document.getElementById('timerDisplay');
  const startPauseBtn = document.getElementById('startPauseBtn');
  const resetBtn = document.getElementById('resetBtn');
  const workModeBtn = document.getElementById('workMode');
  const breakModeBtn = document.getElementById('breakMode');

  function formatTime(seconds) {
    const m = Math.floor(seconds / 60);
    const s = seconds % 60;
    return String(m).padStart(2, '0') + ':' + String(s).padStart(2, '0');
  }

  function updateDisplay() {
    timerDisplay.textContent = formatTime(timeLeft);
  }

  function updateModeButtons() {
    const isWork = currentMode === 'work';
    workModeBtn.classList.toggle('active', isWork);
    breakModeBtn.classList.toggle('active', !isWork);
    workModeBtn.setAttribute('aria-pressed', String(isWork));
    breakModeBtn.setAttribute('aria-pressed', String(!isWork));
  }

  function setMode(mode) {
    if (currentMode === mode) return;
    stopTimer();
    currentMode = mode;
    timeLeft = mode === 'work' ? WORK_TIME : BREAK_TIME;
    updateDisplay();
    updateModeButtons();
  }

  function startTimer() {
    if (isRunning) return;
    isRunning = true;
    startPauseBtn.textContent = 'Pause';
    startPauseBtn.setAttribute('aria-label', 'Pause timer');
    timerId = setInterval(function() {
      timeLeft--;
      updateDisplay();
      if (timeLeft <= 0) {
        stopTimer();
        if (currentMode === 'work') {
          setMode('break');
        } else {
          setMode('work');
        }
        startTimer();
      }
    }, 1000);
  }

  function stopTimer() {
    if (timerId !== null) {
      clearInterval(timerId);
      timerId = null;
    }
    isRunning = false;
    startPauseBtn.textContent = 'Start';
    startPauseBtn.setAttribute('aria-label', 'Start timer');
  }

  function resetTimer() {
    stopTimer();
    timeLeft = currentMode === 'work' ? WORK_TIME : BREAK_TIME;
    updateDisplay();
  }

  startPauseBtn.addEventListener('click', function() {
    if (isRunning) {
      stopTimer();
    } else {
      startTimer();
    }
  });

  resetBtn.addEventListener('click', resetTimer);

  workModeBtn.addEventListener('click', function() {
    setMode('work');
  });

  breakModeBtn.addEventListener('click', function() {
    setMode('break');
  });

  updateDisplay();
  updateModeButtons();
})();
